export type AuthUser = {
  id: number;
  username: string;
  email: string;
  is_admin: boolean;
  plan: string;
};

export type AuthStatus =
  | { authenticated: false }
  | { authenticated: true; user: AuthUser };

export function authUserLabel(user: AuthUser): string {
  return user.email || user.username || "?";
}

export function authUserInitial(label: string): string {
  const trimmed = label.trim();
  return trimmed ? trimmed.charAt(0).toUpperCase() : "?";
}

export async function fetchAuthStatus(): Promise<AuthStatus> {
  try {
    const res = await fetch("/api/auth/status", { credentials: "same-origin" });
    if (!res.ok) return { authenticated: false };
    const payload = await res.json();
    if (!payload?.authenticated || !payload.user) {
      return { authenticated: false };
    }
    return {
      authenticated: true,
      user: {
        id: payload.user.id,
        username: payload.user.username || "",
        email: payload.user.email || "",
        is_admin: Boolean(payload.user.is_admin),
        plan: payload.user.plan || "free",
      },
    };
  } catch {
    return { authenticated: false };
  }
}

"use client";

import { useEffect, useState } from "react";
import {
  fetchAuthStatus,
  type AuthUser,
} from "@/lib/auth";

export type AuthView =
  | { status: "loading"; user: null }
  | { status: "signedOut"; user: null }
  | { status: "signedIn"; user: AuthUser };

export function useAuthStatus(): AuthView {
  const [view, setView] = useState<AuthView>({ status: "loading", user: null });

  useEffect(() => {
    let cancelled = false;
    fetchAuthStatus().then((result) => {
      if (cancelled) return;
      if (result.authenticated) {
        setView({ status: "signedIn", user: result.user });
        return;
      }
      setView({ status: "signedOut", user: null });
    });
    return () => {
      cancelled = true;
    };
  }, []);

  return view;
}

